ALTER TABLE users ADD COLUMN mfa_secret VARCHAR(255) NULL, ADD COLUMN mfa_enabled BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN mfa_last_step BIGINT NULL;
CREATE TABLE mfa_recovery_codes (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, code_hash CHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, KEY(user_id));
CREATE TABLE mfa_challenges (token_hash CHAR(64) PRIMARY KEY, user_id INT NOT NULL, attempts INT NOT NULL DEFAULT 0, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
